TRIGGERED_ABILITY.TRIGGER:
if EffectSource() ~= nil then
	return TriggerObject() == EffectSource():GetParent()
end

STATIC_ABILITY.CONTINUOUS_ACTION:
if EffectSource() ~= nil then local characteristics = EffectSource():GetCurrentCharacteristics() local filter = ClearFilter()
filter:Add( FE_SUBTYPE, OP_IS, LAND_TYPE_MOUNTAIN ) filter:Add( FE_CONTROLLER, OP_IS, EffectController())
if filter:CountStopAt(1) == 1 then characteristics:Power_Add( 1 ) characteristics:Toughness_Add( 1 ) end end

if EffectSource() ~= nil then local characteristics = EffectSource():GetCurrentCharacteristics() local filter = ClearFilter()
filter:Add( FE_SUBTYPE, OP_IS, LAND_TYPE_PLAINS ) filter:Add( FE_CONTROLLER, OP_IS, EffectController())
if filter:CountStopAt(1) == 1 then characteristics:Power_Add( 1 ) characteristics:Toughness_Add( 1 ) end end
